begin;
with j as (select * from jsonb_to_recordset($law7d0039$[{"code_id":"BK_RF","article_number":"78.3","version_date":"1998-07-31","article_text":"1. В федеральном бюджете могут предусматриваться субсидии государственным корпорациям (компаниям) ,  публично-правовым компаниям:\n\n1)  в виде имущественного взноса Российской Федерации,  в том числе на цели,  указанные в подпунктах 3 и 31 настоящего пункта; (В редакции Федерального закона от 01.04.2020 № 71-ФЗ)\n\n2)  на осуществление государственных полномочий (функций) ,  возложенных на них федеральными законами и (или)  иными нормативными правовыми актами,  предусматривающими создание государственных корпораций (компаний) ,  публично-правовых компаний,  и на оказание государственных услуг,  включая субсидии на осуществление деятельности по доверительному управлению автомобильными дорогами общего пользования федерального значения,  переданными (подлежащими передаче)  в доверительное управление в соответствии с Федеральным законом от 17 июля 2009 года № 145-ФЗ \"О Государственной компании \"Российские автомобильные дороги\" и о внесении изменений в отдельные законодательные акты Российской Федерации\";\n\n21)  на осуществление капитальных вложений в создание и развитие государственных информационных систем в случае определения федеральными законами государственной корпорации,  государственной компании,  публично-правовой компании оператором указанных систем; (Дополнение подпунктом - Федеральный закон от 21.11.2022 № 448-ФЗ)\n\n3)  на осуществление капитальных вложений в объекты капитального строительства,  находящиеся в собственности государственных корпораций (компаний) ,  публично-правовых компаний,  и (или)  на приобретение ими объектов недвижимого имущества либо в целях предоставления взноса в уставные (складочные)  капиталы юридических лиц,  акции (доли)  которых принадлежат указанным государственным корпорациям (компаниям) ,  публично-правовым компаниям,  на осуществление капитальных вложений в объекты капитального строительства,  находящиеся в собственности таких юридических лиц,  и (или)  на приобретение ими объектов недвижимого имущества или для последующего предоставления взноса в уставные (складочные)  капиталы дочерних обществ таких юридических лиц на осуществление капитальных вложений в объекты капитального строительства,  находящиеся в собственности указанных дочерних обществ,  и (или)  на приобретение указанными дочерними обществами объектов недвижимого имущества (за исключением капитальных вложений,  осуществляемых в целях реализации мероприятий по завершению строительства объектов незавершенного строительства в соответствии с Федеральным законом от 29 июля 2017 года № 218-ФЗ \"О публично-правовой компании по защите прав граждан - участников долевого строительства при несостоятельности (банкротстве)  застройщиков и о внесении изменений в отдельные законодательные акты Российской Федерации\") ; (В редакции Федерального закона от 26.07.2019 № 202-ФЗ)\n\n31)  на возмещение затрат в связи с ранее осуществленными государственными корпорациями (компаниями) ,  публично-правовыми компаниями капитальными вложениями в объекты капитального строительства,  находящиеся в их собственности или в государственной (муниципальной)  собственности,  в случаях,  установленных федеральными законами; (Дополнение подпунктом - Федеральный закон от 01.04.2020 № 71-ФЗ)\n\n4)  на осуществление деятельности по организации строительства (реконструкции)  автомобильных дорог общего пользования федерального значения,  переданных (подлежащих передаче)  в доверительное управление в соответствии с Федеральным законом от 17 июля 2009 года № 145-ФЗ \"О Государственной компании \"Российские автомобильные дороги\" и о внесении изменений в отдельные законодательные акты Российской Федерации\".\n\n11. Государственным корпорациям могут предоставляться субсидии,  предусмотренные подпунктом 1 пункта 1 настоящей статьи,  в целях исполнения принятых в случаях,  определенных федеральными законами,  преду\n\nсубсидии на осуществление указанными учреждениями и предприятиями капитальных вложений в объекты капитального строительства государственной (муниципальной)  собственности или приобретение объектов недвижимого имущества в государственную (муниципальную)  собственность (далее в настоящей главе - капитальные вложения в объект государственной (муниципальной)  собственности)  с последующим увеличением стоимости основных средств,  находящихся на праве оперативного управления у этих учреждений либо на праве оперативного управления или хозяйственного ведения у этих предприятий,  а также уставного фонда указанных предприятий,  основанных на праве хозяйственного ведения,  в соответствии с решениями,  указанными в пунктах 2 и 3 настоящей статьи,  с учетом положений статьи 1791 настоящего Кодекса. (В редакции  федеральных законов от 18.07.2017 № 178-ФЗ,  от 25.12.2023 № 628-ФЗ)\n\n2. Принятие решений о предоставлении бюджетных ассигнований на осуществление за счет предусмотренных настоящей статьей субсидий из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджетов субъектов Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местных бюджетов капитальных вложений в объекты государственной собственности Российской Федерации,  государственной собственности субъекта Российской Федерации,  муниципальной собственности и предоставление указанных субсидий осуществляются в порядках,  установленных соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\n3. Решение о предоставлении бюджетных ассигнований за счет предусмотренных настоящей статьей субсидий из федерального бюджета (бюджетов государственных внебюджетных фондов Российской Федерации)  на осуществление капитальных вложений в объекты государственной собственности Российской Федерации,  находящиеся в оперативном управлении или хозяйственном ведении:\n\nфедерального государственного учреждения стоимостью 3 миллиарда рублей и более,  а также федерального государственного загранучреждения и федерального государственного унитарного предприятия независимо от стоимости,  принимается в форме правового акта  Правительства  Российской Федерации; (В редакции федеральных законов от 22.10.2014 № 311-ФЗ,  от 22.12.2020 № 448-ФЗ)\n\nфедерального государственного учреждения стоимостью менее 3 миллиардов рублей принимается в установленном Правительством Российской Федерации порядке,  в том числе в случаях,  определенных Правительством Российской Федерации,  в форме правового акта федерального органа исполнительной власти или иной организации,  осуществляющих в соответствии с настоящим Кодексом полномочия главного распорядителя средств федерального бюджета (органа управления государственным внебюджетным фондом Российской Федерации) . (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nВ случае принятия решений,  предусмотренных настоящим пунктом,  в отношении объектов государственной собственности Российской Федерации стоимостью 1, 5 миллиарда рублей и более информация о таких решениях направляется в Государственную Думу и Совет Федерации Федерального Собрания Российской Федерации в порядке,  установленном Правительством Российской Федерации,  в течение 10 дней со дня их принятия. (Дополнение абзацем - Федеральный закон от 22.12.2020 № 448-ФЗ)\n\n31. В случае,  если подготовка обоснования инвестиций для объекта капитального строительства в соответствии с законодательством Российской Федерации является обязательной,  решения о предоставлении субсидий на осуществление капитальных вложений в такие объекты капитального строительства государственной (муниципальной)  собственности принимаются в том числе на основании подготовленного в установленном законодательством Российской Федерации порядке обоснования инвестиций и результатов его технологического и ценового аудита,  а также утвержденного задания на проектирование.\n\nПорядок принятия решений о предоставлении субсидий на подготовку обоснования инвестиций и проведение его технологического и ценового аудита из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации,  бюджета субъекта Российской Федерации и бюджетов территориальных государственных внебюджетных фондов,  местного бюджета и порядок предоставления указанных субсидий,  включая требования к соглашениям о предоставлении субсидий,  срокам и условиям их предоставления,  устанавливаются соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nРешения о предоставлении субсидий на подготовку обоснования инвестиций и проведение его технологического и ценового аудита из федерального бюджета и бюджетов государственных внебюджетных фондов Российской Федерации принимаются Правительством Российской Федерации.\n\n(Дополнение пунктом - Федеральный закон от 19.07.2018 № 222-ФЗ)\n\n4. Предоставление предусмотренной настоящей статьей субсидии осуществляется в соответствии с соглашением о предоставлении субсидии,  заключаемым между получателем бюджетных средств,  предоставляющим субсидию,  и бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием (далее в настоящей статье - соглашение о предоставлении субсидии) ,  на срок действия утвержденных лимитов бюджетных обязательств с учетом положений абзаца четырнадцатого настоящего пункта.\n\nСоглашение о предоставлении субсидии может быть заключено в отношении нескольких объектов капитального строительства государственной (муниципальной)  собственности и (или)  объектов недвижимого имущества,  приобретаемых в государственную (муниципальную)  собственность,  и должно содержать в том числе:\n\nцель предоставления субсидии и ее объем с разбивкой по годам в отношении каждого объекта,  на строительство (реконструкцию,  в том числе с элементами реставрации,  техническое перевооружение)  или приобретение которого предоставляется субсидия,  с указанием его наименования,  мощности,  сроков строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  или приобретения,  стоимости объекта,  соответствующих решениям,  указанным в пунктах 2 и 3 настоящей статьи,  а также общего объема капитальных вложений в объект государственной (муниципальной)  собственности за счет всех источников финансового обеспечения,  в том числе объема предоставляемой субсидии,  соответствующих решениям,  указанным в пунктах 2 и 3 настоящей статьи. В случае предоставления субсидии из федерального бюджета объем предоставляемой субсидии должен соответствовать объему бюджетных ассигнований на предоставление субсидии,  определенному в соответствии со статьей 1791 настоящего Кодекса; (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\nположения,  устанавливающие права и обязанности сторон соглашения о предоставлении субсидии и порядок их взаимодействия при реализации указанного соглашения;\n\nусловие о соблюдении автономным учреждением,  государственным (муниципальным)  унитарным предприятием при использовании субсидии положений,  установленных законодательством Российской Федерации о контрактной системе в сфере закупок товаров,  работ,  услуг для обеспечения государственных и муниципальных нужд;\n\nположения,  устанавливающие обязанность федерального автономного учреждения,  автономного учреждения субъекта Российской Федерации,  муниципального автономного учреждения,  федерального государственного унитарного предприятия,  государственного унитарного предприятия субъекта Российской Федерации,  муниципального унитарного предприятия по открытию лицевого счета для учета операций с субсидиями соответственно в органе Федерального казначейства,  финансовом органе субъекта Российской Федерации или финансовом органе муниципального образования,  а в случае направления высшим исполнительным органом субъекта Российской Федерации (местной администрацией)  в орган Федерального казначейства обращения в соответствии со статьей 2202 настоящего Кодекса - в органе Федерального казначейства в порядке,  установленном Федеральным казначейством; (В редакции  федеральных законов от 22.10.2014 № 311-ФЗ,  от 18.07.2017 № 178-ФЗ,  от 01.07.2021 № 244-ФЗ,  от 14.04.2023 № 128-ФЗ)\n\nсроки (порядок определения сроков)  перечисления субсидии,  а также положения,  устанавливающие обязанность перечисления субсидии на лицевой счет,  указанный в абзаце шестом настоящего пункта;\n\nположения,  устанавливающие право получателя бюджетных средств,  предоставляющего субсидию,  на проведение проверок соблюдения бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием условий,  установленных соглашением о предоставлении субсидии;\n\nпорядок возврата бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием средств в объеме остатка не использованной на начало очередного финансового года ранее перечисленной этому учреждению,  предприятию субсидии в случае отсутствия принятого в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования,  решения получателя бюджетных средств,  предоставляющего субсидию,  о наличии потребности направления этих средств на цели предоставления субсидии; (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nпорядок возврата сумм,  использованных бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием,  в случае установления по результатам проверок фактов нарушения этим учреждением,  предприятием целей и условий,  определенных соглашением о предоставлении субсидии;\n\nположения,  предусматривающие приостановление предоставления субсидии либо сокращение объема предоставляемой субсидии в связи с нарушением бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием условия о софинансировании капитальных вложений в объект государственной (муниципальной)  собственности за счет иных источников,  в случае,  если соглашением о предоставлении субсидии предусмотрено указанное условие;\n\nпорядок и сроки представления отчетности об использовании субсидии бюджетным или автономным учреждением,  государственным (муниципальным)  унитарным предприятием;\n\nслучаи и порядок внесения изменений в соглашение о предоставлении субсидии,  в том числе в случае уменьшения в соответствии с настоящим Кодексом получателю бюджетных средств ранее доведенных в установленном порядке лимитов бюджетных обязательств на предоставление субсидии,  а также случаи и порядок досрочного прекращения соглашения о предоставлении субсидии.\n\nРешениями  Правительства  Российской Федерации,  высшего исполнительного органа субъекта Российской Федерации,  местной администрации муниципального образования,  принимаемыми в порядке,  установленном соответственно Правительством Российской Федерации,  высшим исполнительным органом субъекта Российской Федерации,  местной администрацией муниципального образования,  получателям бюджетных средств может быть предоставлено право заключать соглашения о предоставлении субсидий на срок реализации соответствующих решений,  превышающий срок действия утвержденных получателю бюджетных средств лимитов бюджетных обязательств на предоставление субсидий. (В редакции  Федерального закона от 14.04.2023 № 128-ФЗ)\n\nПорядок взыскания средств в объеме остатка не использованной на начало очередного финансового года субсидии при отсутствии решения получателя бюджетных средств,  предоставившего субсидию,  о наличии потребности направления этих средств на цели предоставления субсидии устанавливается соответствующим финансовым органом с учетом общих требований,  установленных Министерством финансов Российской Федерации.\n\nПоложения абзацев шестого и седьмого настоящего пункта не распространяются на объекты государственной собственности Российской Федерации,  строительство (реконструкция,  в том числе с элементами реставрации,  техническое перевооружение)  или приобретение которых осуществляется за пределами территории Российской Федерации. (Дополнение абзацем - Федеральный закон от 22.10.2014 № 311-ФЗ)  (В редакции  Федерального закона от 25.12.2023 № 628-ФЗ)\n\n5. В договоры,  заключенные в целях строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  объектов капитального строительства государственной (муниципальной)  собственности или приобретения объектов недвижимого имущества в государственную (муниципальную)  собственность,  подлежащие оплате за счет предусмотренной настоящей статьей субсидии,  включается условие о возможности изменения размера и (или)  сроков оплаты и (или)  объема работ в случае уменьшения в соответствии с настоящим Кодексом получателю бюджетных средств ранее доведенных в установленном порядке лимитов бюджетных обязательств на предоставление субсидии.\n\nСторона договора,  предусмотренного настоящим пунктом,  вправе потребовать от бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия возмещения понесенного реального ущерба,  непосредственно обусловленного изменениями условий указанного договора.\n\nВ случае признания в соответствии с настоящим Кодексом утратившими силу положений закона (решения)  о бюджете на текущий финансовый год и плановый период в части,  относящейся к плановому периоду,  бюджетное или автономное учреждение,  государственное (муниципальное)  унитарное предприятие вправе не принимать решение о расторжении предусмотренных настоящим пунктом договоров,  подлежащих оплате в плановом периоде,  при условии заключения дополнительных соглашений к указанным договорам,  определяющих условия их исполнения в плановом периоде. (Дополнение абзацем - Федеральный закон от 15.02.2016 № 23-ФЗ)\n\n6. Соглашения о предоставлении субсидий в отношении объектов,  срок строительства (реконструкции,  в том числе с элементами реставрации,  технического перевооружения)  или приобретения которых превышает срок действия лимитов бюджетных обязательств,  утвержденных на предоставление предусмотренных настоящей статьей субсидий,  заключаются на срок реализации решений,  указанных в пунктах 2 и 3 настоящей статьи,  с учетом положений,  установленных абзацем четырнадцатым пункта 4 настоящей статьи.\n\n7. Не допускается при исполнении соответствующего бюджета предоставление предусмотренных настоящей статьей субсидий в отношении объектов капитального строительства или объектов недвижимого имущества государственной (муниципальной)  собственности,  по которым принято решение о подготовке и реализации бюджетных инвестиций в объекты государственной и муниципальной собственности,  за исключением случая,  указанного в абзаце втором настоящего пункта. (В редакции Федерального закона от 29.12.2015 № 406-ФЗ)\n\nПри исполнении соответствующего бюджета допускается предоставление субсидий на осуществление капитальных вложений в объекты государственной (муниципальной)  собственности,  указанные в абзаце первом настоящего пункта,  в случае изменения в установленном порядке типа казенного учреждения,  являющегося государственным (муниципальным)  заказчиком при осуществлении бюджетных инвестиций,  предусмотренных статьей 79 настоящего Кодекса,  на бюджетное или автономное учреждение или изменения его организационно-правовой формы на государственное (муниципальное)  унитарное предприятие после внесения соответствующих изменений в решение о подготовке и реализации бюджетных инвестиций в указанные объекты с внесением изменений в ранее заключенные казенным учреждением государственные (муниципальные)  контракты в части замены стороны договора - казенного учреждения на бюджетное или автономное учреждение,  государственное (муниципальное)  унитарное предприятие и вида договора - государственного (муниципального)  контракта на гражданско-правовой договор бюджетного или автономного учреждения,  государственного (муниципального)  унитарного предприятия. (Дополнение абзацем - Федеральный закон от 29.12.2015 № 406-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 28.12.2013 № 418-ФЗ)","article_title":"Статья 78.3. Предоставление субсидий государственным корпорациям (компаниям) ,  публично-правовым компаниям","amendment_eo_number":"145-ФЗ","amendment_date":"1998-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"685ef1c3b580b900a3f5361a473e5d49229ecf8aeeefbee508dfce7433484d2f"}]$law7d0039$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
